WITH page_returns AS (SELECT wp.wp_web_page_sk, wp.wp_url, wp.wp_web_page_id, wp.wp_customer_sk, AVG(wr.wr_return_amt_inc_tax) AS avg_return_amt_inc_tax, COUNT(DISTINCT wr.wr_order_number) AS distinct_orders FROM web_page wp JOIN web_returns wr ON wr.wr_web_page_sk = wp.wp_web_page_sk GROUP BY wp.wp_web_page_sk, wp.wp_url, wp.wp_web_page_id, wp.wp_customer_sk HAVING COUNT(*) > 3) SELECT pr.wp_web_page_id, pr.wp_url, c.c_customer_id, pr.avg_return_amt_inc_tax, pr.distinct_orders, CASE WHEN pr.avg_return_amt_inc_tax >= 150 THEN 'Elevated' ELSE 'Standard' END AS risk_category, ROW_NUMBER() OVER (PARTITION BY c.c_preferred_cust_flag ORDER BY pr.avg_return_amt_inc_tax DESC) AS flagged_rank, COALESCE(sr_agg.store_net_loss, 0) AS owner_store_loss FROM page_returns pr JOIN customer c ON pr.wp_customer_sk = c.c_customer_sk LEFT JOIN (SELECT sr.sr_customer_sk, SUM(sr.sr_net_loss) AS store_net_loss FROM store_returns sr GROUP BY sr.sr_customer_sk) sr_agg ON sr_agg.sr_customer_sk = c.c_customer_sk WHERE c.c_preferred_cust_flag = 'Y' ORDER BY pr.avg_return_amt_inc_tax DESC, pr.distinct_orders ASC LIMIT 25
